(()=>{'use strict';const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),KEY='common-ground-v1',copy=v=>JSON.parse(JSON.stringify(v));let initial=Emergence.create(),world=copy(initial),runs=[],notes='',label='',log=[],busy=false,controller=null,playing=false,selected=null;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved){validate(saved);({initial,world,notes,label,runs,log}=saved);}}catch(e){$('#status').textContent='Previous run could not be loaded. Import an exported run to recover it.';}
function validate(x){if(x?.world?.format!=='emergence-world'||![1,2].includes(x.world.version)||x.initial?.format!=='emergence-world'||!Array.isArray(x.world.journal)||x.world.journal.length>2000)throw Error('Unsupported run');const replay=Emergence.replay(x.initial,x.world.journal);if(JSON.stringify(replay)!==JSON.stringify(x.world))throw Error('Run failed deterministic replay validation');}
function save(){try{localStorage.setItem(KEY,JSON.stringify({initial,world,runs,notes,label,log}));}catch(e){$('#status').textContent='Save failed: '+e.message+'. Export this run now.';}}
function show(html){$('#detail').innerHTML=html;$('#dialog').showModal();}$('#close').onclick=()=>$('#dialog').close();
function render(){const m=Emergence.metrics(world);$('#turn').textContent='TURN '+String(world.turn).padStart(3,'0');$('#metrics').innerHTML=Object.entries(m).map(([k,v])=>'<div class="metric"><b>'+v+'</b><span>'+esc(k)+'</span></div>').join('');$('#map').innerHTML=Array.from({length:96},(_,i)=>{const x=i%12,y=Math.floor(i/12),site=world.sites.find(s=>s.x===x&&s.y===y),jar=world.objects.find(o=>o.x===x&&o.y===y&&o.holder===null),buildings=(world.structures||[]).filter(b=>b.x===x&&b.y===y),visits=world.footprints?.[x+','+y]||0;return '<div class="cell '+(site?.kind||'')+(visits>=6?' travelled':'')+'" title="'+x+','+y+(site?' · '+site.name+' '+site.stock+'/'+site.capacity:'')+'">'+(site?'<span>'+({water:'◉',food:'✳',wood:'♣'}[site.kind])+'</span>':'')+(jar?'<span>▱</span>':'')+buildings.map(b=>'<button class="building '+(b.progress<b.required?'unfinished':'')+'" data-building="'+b.id+'" title="'+esc(b.id)+'">'+({store:'▣',shelter:'⌂',garden:'❧'}[b.kind])+'</button>').join('')+world.agents.filter(a=>a.alive&&a.x===x&&a.y===y).map(a=>'<button class="person" data-person="'+a.id+'" title="'+esc(a.name)+'">'+a.name[0]+'</button>').join('')+'</div>';}).join('');$('#people').innerHTML=world.agents.map(a=>'<div class="agent" data-person="'+a.id+'"><strong>'+a.name+'</strong> <small>'+(!a.alive?'DECEASED':a.x+','+a.y)+'</small><div class="bars">'+[a.food/40,a.water/40,a.energy/100].map(v=>'<div class="bar"><i style="width:'+Math.min(100,v*100)+'%"></i></div>').join('')+'</div><div class="last">'+esc(a.last)+'</div></div>').join('');document.querySelectorAll('[data-person]').forEach(el=>el.onclick=()=>{selected=Number(el.dataset.person);const a=world.agents.find(a=>a.id===selected);show('<h2>'+esc(a.name)+'</h2><p>Food '+a.food+' · Water '+a.water+' · Energy '+a.energy+' · Health '+a.health+'</p><h3>Personal objective</h3><p>'+esc(a.goal||'No objective stated')+'</p><h3>Private record</h3>'+a.memory.slice().reverse().map(m=>'<p><small>Turn '+m.turn+' · '+esc(m.kind)+'</small><br>'+esc(m.from?m.from+': ':'')+esc(m.text)+'</p>').join(''));});renderPlaces();renderSummaries();renderConversations();$('#events').innerHTML=world.events.slice(-50).reverse().map(e=>'<div class="event '+e.kind+'"><small>TURN '+e.turn+' · '+esc(world.agents.find(a=>a.id===e.actor)?.name||'WORLD')+' · '+e.kind.toUpperCase()+'</small>'+esc(e.text)+'</div>').join('')||'<p>No events yet. Advance a turn to begin.</p>';$('#label').value=label;$('#notes').value=notes;$('#comparisons').innerHTML=runs.slice(-5).map(r=>'<p class="small">'+esc(r.label)+' · seed '+r.seed+' · '+r.scarcity+' · turn '+r.metrics.turn+' · alive '+r.metrics.alive+' · transfers '+r.metrics.transfers+'</p>').join('');$('#chart').innerHTML='<span class="small">RESOURCE STOCK · WATER / FOOD</span><svg viewBox="0 0 400 70" aria-label="Current water and food stock"><rect x="0" y="10" width="'+world.sites[0].stock/18*400+'" height="15" fill="#729ca9"/><rect x="0" y="40" width="'+world.sites[1].stock/18*400+'" height="15" fill="#789663"/></svg>';$('#step').disabled=busy;$('#new').disabled=busy;$('#import').disabled=busy;$('#cancel').hidden=!busy;$('#play').textContent=playing?'Pause':'Run';}
let summaryWorld=null,summaryReports=[];
function renderSummaries(){if(summaryWorld!==world){summaryReports=CommonGroundSummary.build(initial,world);summaryWorld=world;}const reports=summaryReports;$('#summaries').innerHTML=reports.slice().reverse().map(r=>'<details class="briefing" '+(r===reports[reports.length-1]?'open':'')+'><summary>Turns '+r.start+'–'+r.end+(r.complete?'':' · in progress')+'</summary><p>'+esc(r.text)+'</p>'+r.markers.map(m=>'<p class="milestone">'+esc(m)+'</p>').join('')+'<details><summary>Recorded evidence ('+r.evidence.length+' events)</summary>'+r.evidence.map(e=>'<p class="small">Turn '+e.turn+' · '+esc(world.agents.find(a=>a.id===e.actor)?.name||'World')+' · '+esc(e.kind)+': '+esc(e.text)+'</p>').join('')+'</details></details>').join('')||'<p>Advance a turn to start the first briefing.</p>';}
function renderPlaces(){const structures=world.structures||[],name=id=>world.agents.find(a=>a.id===id)?.name||'World';$('#places').innerHTML=structures.map(b=>'<button class="place-card" data-building="'+esc(b.id)+'"><strong>'+esc(b.id)+'</strong><span>'+b.x+','+b.y+' · '+(b.progress<b.required?'Project '+b.progress+'/'+b.required:b.kind==='shelter'?'Durability '+b.durability+'/12':b.kind==='garden'?'Food '+b.stock+'/12':'Food '+b.stock.food+' · Water '+b.stock.water+' · Wood '+b.stock.wood)+'</span><span>Contributors: '+esc(b.contributors.map(name).join(', ')||'None')+'</span><span>Users: '+esc(b.users.map(name).join(', ')||'None yet')+'</span></button>').join('')||'<p>No lasting changes yet. Agents can build stores and shelters or plant gardens. Nothing is built automatically.</p>';document.querySelectorAll('[data-building]').forEach(el=>el.onclick=()=>{const b=structures.find(b=>b.id===el.dataset.building);show('<h2>'+esc(b.id)+'</h2><p>Created turn '+b.created+' at '+b.x+','+b.y+'. Claims do not enforce ownership; anyone can use a completed structure.</p><h3>Recorded history</h3>'+b.history.slice().reverse().map(h=>'<p>Turn '+h.turn+' · '+esc(name(h.actor))+' · '+esc(h.kind)+' · '+h.amount+'</p>').join(''));});$('#experiment-version').textContent=world.version===2?'SETTLEMENT WORLD · RULES 2':'LEGACY RUN · Start a new experiment for building and gardens';}
function renderConversations(){const speech=world.journal.flatMap(j=>j.events.filter(e=>e.kind==='speech')),latest=speech.slice(-40).reverse();$('#speech-count').textContent=speech.length+' SPOKEN LINES';$('#conversations').innerHTML=latest.map(e=>{const speaker=world.agents.find(a=>a.id===e.actor),listeners=world.agents.filter(a=>a.id!==e.actor&&a.memory.some(m=>m.kind==='heard'&&m.turn===e.turn&&m.from===speaker?.name&&m.text===e.text));return '<article class="utterance"><small>TURN '+e.turn+' · '+esc(speaker?.name||'Unknown speaker')+'</small><blockquote>'+esc(e.text)+'</blockquote><span class="small">'+(listeners.length?'Remembered by '+listeners.map(a=>esc(a.name)).join(', '):'No listener memory retained; delivery cannot be confirmed here.')+'</span></article>';}).join('')||'<p>No speech has been recorded in this run. The speech count stays at zero when agents choose silence or no model turn has completed.</p>';}
async function step(){if(busy)return;if(!world.agents.some(a=>a.alive)){playing=false;$('#status').textContent='The population has died. Inspect the record or start a comparison run.';render();return;}busy=true;controller=new AbortController();const snapshot=copy(world),entries={};$('#status').textContent='Individuals are deciding from their private observations…';render();try{if(world.version===2){const healthURL=new URL(window.INHABITANT_API_URL);healthURL.pathname='/health';const health=await fetch(healthURL,{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(10000)])});if(!health.ok)throw Error('Backend health check failed (HTTP '+health.status+'). No turn consumed.');const info=await health.json();if(info.contracts?.sandbox<2||!info.contracts?.sandbox)throw Error('Settlement actions need the updated model backend. Deploy GitHub main on Render. No turn consumed.');}const outcome=await TurnKernel.collect(world.agents.filter(a=>a.alive),async(a,signal)=>{const req={actor:a.id,view:Emergence.view(snapshot,a.id)},started=Date.now();try{const url=new URL(window.INHABITANT_API_URL);url.pathname='/api/sandbox';const res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(req),signal});const raw=await res.text();log.push({turn:world.turn,actor:a.id,ms:Date.now()-started,status:res.status,response:raw.slice(0,6000)});if(!res.ok)throw Object.assign(Error((res.status===404?'The deployed backend has no /api/sandbox route. Deploy the latest GitHub main branch on Render.':(()=>{try{return JSON.parse(raw).error||raw.slice(0,300);}catch{return raw.slice(0,300);}})())+' (HTTP '+res.status+')'),{code:'SANDBOX_HTTP_'+res.status});return JSON.parse(raw).command;}catch(e){log.push({turn:world.turn,actor:a.id,error:e.message});throw e;}},(v,a)=>({actor:a.id,command:Emergence.command(v)}),{signal:controller.signal,deadlineMs:15000,onFault:f=>entries[f.actor]={error:f.reason}});
if(!outcome.commands.length&&outcome.faults.every(f=>f.failureKind!=='invalid-response'))throw Error('Run paused without consuming a turn. '+[...new Set(outcome.faults.map(f=>f.reason))].join(' · '));for(const r of outcome.commands)entries[r.actor]=r.command;for(const f of outcome.faults)delete entries[f.actor];world=Emergence.step(snapshot,entries,crypto.randomUUID());log=log.slice(-150);$('#status').textContent='Turn '+world.turn+' committed · '+outcome.commands.length+' accepted actions · '+outcome.faults.length+' missing actions. No referee calls.';save();}catch(e){playing=false;$('#status').textContent=e.name==='AbortError'?'Cancelled. No turn consumed.':e.message;}finally{busy=false;controller=null;render();if(playing)setTimeout(step,1500);}}
$('#step').onclick=step;$('#play').onclick=()=>{playing=!playing;render();if(playing)step();};$('#cancel').onclick=()=>controller?.abort();$('#new').onclick=()=>{if(world.turn)runs.push({label:label||'Unlabelled',seed:initial.seed,scarcity:initial.scarcity,metrics:Emergence.metrics(world)});initial=Emergence.create(Number($('#seed').value)||42,$('#scarcity').value);world=copy(initial);label='';notes='';log=[];playing=false;save();render();$('#status').textContent='Settlement experiment ready. Build, plant, store or explore; no social roles or cooperation are assigned.';};$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({initial,world,runs,notes,label,log},null,2)],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='common-ground-turn-'+world.turn+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#import').onchange=async e=>{try{playing=false;const x=JSON.parse(await e.target.files[0].text());validate(x);({initial,world}=x);runs=x.runs||[];notes=x.notes||'';label=x.label||'';log=x.log||[];save();render();$('#status').textContent='Imported and replay-verified.';}catch(e){$('#status').textContent='Import rejected: '+e.message;}};$('#replay').onclick=()=>{try{validate({initial,world});$('#status').textContent='Replay matches exactly. No model requests were made.';}catch(e){$('#status').textContent=e.message;}};$('#label').oninput=e=>{label=e.target.value;save();};$('#notes').oninput=e=>{notes=e.target.value;save();};$('#rules').onclick=()=>show((world.version===2?'<h2>Lasting changes, open access</h2><p>Forgiving mode spends one food and water every second turn; scarce mode every turn. Energy costs one per turn. Each agent begins with two carried food. People never block access or movement. Sharing tiles is allowed.</p><p>Gather wood at the copse. A store takes two wood contributions; a shelter takes four, one wood per build action. Unfinished projects persist for anyone to finish. Stores hold 24 food, water and wood each; water transport requires a jar. Anyone may deposit, withdraw, eat or drink at a completed store.</p><p>Plant a garden with two carried food. It grows two food every third turn after planting if tended within six turns, up to 12. Harvest to carry or eat there. Shelters restore up to 26 energy and two health when resting. Durability falls by one every six turns; one wood repairs four durability, capped at 12. A worn-out shelter requires repair before use.</p><p>Map trails show repeated occupancy, not proof of purposeful routes. Structure histories distinguish contributors from users. No settlement, trade, ownership or cooperation is scripted.</p>':'<h2>A small world with stable rules</h2><p>Each turn permits one action and optional speech. Movement covers at most two tiles. Drinking or eating one stock unit restores five reserve units, capped at 40. Everyone spends one food, water and energy per turn. Empty food causes four health damage; empty water causes six. Rest restores up to 18 energy before upkeep.</p><p>The spring and grove are finite shared stocks. Every third turn they renew by six units in forgiving conditions, or two in scarce conditions, up to capacity 18. A person carries up to eight food and one jar. Jars hold eight water. Fill at the spring; pour for a neighbour. Giving and pouring require distance at most one. Speech is heard within two tiles. Action priority rotates each turn.</p><p>Agents see only nearby people, sites and objects, their own body and their own bounded memory. Starting reserves allow 30 turns before deprivation. New experiments place sources within sight of some starting individuals. Personal results and survival warnings are kept separate from nearby speech. No trade, group, leader or cooperative behaviour is scripted. Rules stay fixed during each run. Transfer and speech counts do not establish emergence.</p>'));render();})();
